import{_ as t,Y as o,o as r,c as i,aq as n,H as l}from"./chunks/framework.DBeWS8RL.js";import"./chunks/theme.CKVSPiTA.js";const m=JSON.parse('{"title":"介绍","description":"","frontmatter":{},"headers":[],"relativePath":"zh-cn/guide/home.md","filePath":"zh-cn/guide/home.md"}'),h={name:"zh-cn/guide/home.md"};function s(c,a,u,p,d,f){const e=o("NolebaseGitChangelog");return r(),i("div",null,[a[0]||(a[0]=n('<h1 id="introduction" tabindex="-1">介绍 <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><blockquote><p><code>KavaRef</code> 是一个使用 Kotlin 实现的现代化 Java 反射 API。</p></blockquote><h2 id="background" tabindex="-1">背景 <a class="header-anchor" href="#background" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>这是一个使用 Kotlin 实现的现代化 Java 反射 API，旨在提供更简洁、更易用的 API，同时保留 Java 反射的强大功能。</p><p>项目图标由 <a href="https://github.com/Lagrio" target="_blank" rel="noreferrer">MaiTungTM</a> 设计，名称取自 <strong>K</strong>otlinJ<strong>avaRef</strong>lection，意为使用 Kotlin 实现的 Java 反射。</p><p>它最早诞生于 <a href="https://github.com/HighCapable/YukiHookAPI" target="_blank" rel="noreferrer">YukiHookAPI</a>，后期被解耦合为 <a href="https://github.com/HighCapable/YukiReflection" target="_blank" rel="noreferrer">YukiReflection</a> 项目。</p><p>如你所见，现在 KavaRef 是借助 YukiReflection 的设计思想完全重构的一套全新 API，它们没有从属关系，并将取代 YukiReflection 成为一个全新的反射解决方案。</p><p>如果你正在使用 YukiReflection 或与之相关的 YukiHookAPI 项目，你可以参考 <a href="./../config/migration.html">这里</a> 来迁移反射 API 的写法到 KavaRef。</p><h2 id="usage" tabindex="-1">用途 <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;用途&quot;">​</a></h2><p>KavaRef 采用 Kotlin <strong>lambda</strong> 语法与 Java Builder 风格构建。</p><p>它能取代 <a href="https://pdai.tech/md/java/basic/java-basic-x-reflection.html" target="_blank" rel="noreferrer">Java 原生的反射 API</a>，使用更加人性化的语言实现一套更加完善的反射方案。</p><h2 id="skill-requirements" tabindex="-1">技能要求 <a class="header-anchor" href="#skill-requirements" aria-label="Permalink to &quot;技能要求&quot;">​</a></h2><p>你必须已熟练掌握 Java 原生的反射 API，了解 Java 的类加载机制、字节码结构以及它们在 Kotlin 中的用法 (如果你正在使用 Kotlin)。</p><h2 id="language-requirement" tabindex="-1">语言要求 <a class="header-anchor" href="#language-requirement" aria-label="Permalink to &quot;语言要求&quot;">​</a></h2><p>推荐使用 Kotlin，API 代码构成同样支持 Java，但是在纯 Java 项目中 KavaRef 有可能无法发挥其全部功能和语法糖优势。</p><p>文档全部的 Demo 示例代码都将首先使用 Kotlin 进行描述，如果你完全不会使用 Kotlin 那你将有可能无法更全面地体验和使用 KavaRef 的功能。</p><h2 id="contribution" tabindex="-1">功能贡献 <a class="header-anchor" href="#contribution" aria-label="Permalink to &quot;功能贡献&quot;">​</a></h2><p>本项目的维护离不开各位开发者的支持和贡献，目前这个项目处于初期阶段，可能依然存在一些问题或者缺少你需要的功能， 如果可能，欢迎提交 PR 为此项目贡献你认为需要的功能或前往 <a href="https://github.com/HighCapable/KavaRef/issues" target="_blank" rel="noreferrer">GitHub Issues</a> 向我们提出建议。</p>',18)),l(e)])}const k=t(h,[["render",s]]);export{m as __pageData,k as default};
